// node-postgres: parameterised queries, a batch instead of N+1, and an atomic stock decrement
import { Pool } from "pg";
const pool = new Pool({ max: 10, idleTimeoutMillis: 30_000, connectionTimeoutMillis: 2_000 });

// 1) ALWAYS parameterise: never build SQL by string concatenation (SQL injection)
export const findUser = (email: string) =>
  pool.query("SELECT id, name FROM users WHERE email = $1", [email]).then((r) => r.rows[0]);

// 2) Avoid N+1: fetch parents, then children in ONE query
export async function ordersWithUsers(limit = 50) {
  const { rows: orders } = await pool.query("SELECT * FROM orders ORDER BY id DESC LIMIT $1", [limit]);
  const ids = [...new Set(orders.map((o) => o.user_id))];
  const { rows: users } = await pool.query("SELECT id, name FROM users WHERE id = ANY($1)", [ids]);
  const byId = new Map(users.map((u) => [u.id, u]));
  return orders.map((o) => ({ ...o, user: byId.get(o.user_id) }));
}

// 3) Transaction with row lock; always release the client
export async function reserve(sku: string, qty: number) {
  const c = await pool.connect();
  try {
    await c.query("BEGIN");
    const { rows } = await c.query("SELECT stock FROM items WHERE sku = $1 FOR UPDATE", [sku]);
    if (!rows[0] || rows[0].stock < qty) { await c.query("ROLLBACK"); return false; }
    await c.query("UPDATE items SET stock = stock - $2 WHERE sku = $1", [sku, qty]);
    await c.query("COMMIT");
    return true;
  } catch (e) { await c.query("ROLLBACK"); throw e; } finally { c.release(); }
}

// Mongoose: schema validation, indexes and a safe update (Node)
import mongoose from "mongoose";

const orderSchema = new mongoose.Schema(
  {
    userId: { type: String, required: true, index: true },
    status: { type: String, enum: ["pending", "paid", "cancelled"], default: "pending" },
    items: {
      type: [{ productId: String, name: String, unitPrice: { type: Number, min: 0 }, qty: { type: Number, min: 1, max: 100 } }],
      validate: (v) => v.length > 0 && v.length <= 100, // bounded embedding
    },
    total: { type: Number, required: true },
  },
  { timestamps: true },
);
orderSchema.index({ userId: 1, createdAt: -1 }); // ESR: equality (userId), then sort (createdAt)

const Order = mongoose.model("Order", orderSchema);

// Atomic conditional update: only move pending -> paid, in a single operation
export const markPaid = (id) =>
  Order.findOneAndUpdate({ _id: id, status: "pending" }, { $set: { status: "paid" } }, { new: true });

// Keyset pagination
export const page = (userId, before, limit = 20) =>
  Order.find({ userId, ...(before && { createdAt: { $lt: before } }) }).sort({ createdAt: -1 }).limit(limit).lean();

// Cache-aside with jittered TTL, negative caching and single-flight (ioredis)
import Redis from "ioredis";
const redis = new Redis(process.env.REDIS_URL!);
const inflight = new Map<string, Promise<unknown>>();   // coalesce concurrent misses in this process

const ttl = (base: number) => Math.round(base * (0.9 + Math.random() * 0.2)); // +/-10% jitter

export async function getProduct(id: string) {
  const key = `product:${id}:v1`;
  const hit = await redis.get(key).catch(() => null);            // cache failure must not break reads
  if (hit !== null) return hit === "null" ? null : JSON.parse(hit);

  if (inflight.has(key)) return inflight.get(key);               // single-flight
  const p = (async () => {
    const row = await db.products.find(id);                      // source of truth
    await redis.set(key, JSON.stringify(row ?? null), "EX", row ? ttl(300) : 30).catch(() => {}); // negative caching: 30s
    return row;
  })().finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}

export async function updateProduct(id: string, patch: object) {
  await db.products.update(id, patch);
  await redis.del(`product:${id}:v1`);                           // invalidate by delete, not update
}

// Fixed-window rate limit using INCR + EXPIRE
export async function allow(userId: string, limit = 100) {
  const key = `rl:${userId}:${Math.floor(Date.now() / 60_000)}`;
  const n = await redis.incr(key);
  if (n === 1) await redis.expire(key, 60);
  return n <= limit;
}
